import type { Register } from 'claude-code'
import { scrubDeep, scrubText } from './scrub.ts'

export const register: Register = on => {
  // Every tool, subagents included. Untouched results pass through as core's own.
  on('tool.call', async ($, e, next) => {
    const ran = await next(e)
    if (ran.deny !== undefined) return ran

    if (ran.isError) {
      const text = ran.text ?? ''
      const clean = scrubText(text)
      return clean === text ? ran : { deny: clean }
    }

    const result = scrubDeep(ran.result)
    if (JSON.stringify(result) === JSON.stringify(ran.result)) return ran

    $.ui.toast(`secret-scrub: redacted a secret from ${e.tool} output`)
    // A fresh { result } (no ref/text) makes core record this, not the raw output.
    return { result: result as typeof ran.result, context: ran.context }
  }).catch($ => ({ deny: `${$.plugin.name}: scrub failed, output withheld.` }))
}

