// Shapes drawn from gitleaks findings in synced session transcripts.
// Order matters: specific prefixes before the generic key=value rule.
const RULES: ReadonlyArray<[string, RegExp]> = [
  ['private-key', /-----BEGIN [A-Z ]*PRIVATE KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE KEY-----/g],
  ['github-pat', /(?:gh[pousr]_[A-Za-z0-9]{36,}|github_pat_[A-Za-z0-9_]{22,})\b/g],
  ['gitlab-pat', /glpat-[A-Za-z0-9_-]{20,}/g],
  ['stripe-key', /\b[sr]k_(?:live|test)_[A-Za-z0-9]{16,}\b/g],
  ['slack-token', /xox[abposr]-[A-Za-z0-9-]{10,}/g],
  ['anthropic-key', /sk-ant-[A-Za-z0-9_-]{20,}/g],
  ['openai-key', /\bsk-(?:proj-)?[A-Za-z0-9_-]{32,}/g],
  ['aws-key-id', /\b(?:AKIA|ASIA)[A-Z0-9]{16}\b/g],
  ['google-api-key', /\bAIza[0-9A-Za-z_-]{35}\b/g],
  ['jwt', /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g],
]

// Keeps the user and host, hides the password in scheme://user:pass@host.
const URL_CREDS = /(\b[a-z][a-z0-9+.-]*:\/\/[^\s:/@]+:)([^\s@/]{3,})(@)/gi

// name=value / name: value where the name says secret and the value looks
// like one (12+ token chars with a digit and a letter), so code such as
// `password = process.env.PASSWORD` survives.
const ASSIGN =
  /(\b[\w.-]*(?:api[_-]?key|secret|token|passw(?:or)?d|pwd|credential)[\w.-]*["']?\s*[:=]\s*["']?)([A-Za-z0-9_\-+/=]{12,})/gi

const tag = (name: string) => `[REDACTED:${name}]`

export const scrubText = (s: string): string => {
  let out = s
  for (const [name, re] of RULES) out = out.replace(re, tag(name))
  out = out.replace(URL_CREDS, (_m, pre: string, _p, at: string) => `${pre}${tag('password')}${at}`)
  return out.replace(ASSIGN, (m, pre: string, val: string) =>
    /\d/.test(val) && /[A-Za-z]/.test(val) && !val.startsWith('[REDACTED') ? `${pre}${tag('secret')}` : m,
  )
}

// Rewrites every string in a JSON-shaped value; `base64` fields (images, PDFs) are left whole.
export const scrubDeep = (v: unknown): unknown => {
  if (typeof v === 'string') return scrubText(v)
  if (Array.isArray(v)) return v.map(scrubDeep)
  if (v && typeof v === 'object') {
    return Object.fromEntries(
      Object.entries(v).map(([k, x]) => [k, k === 'base64' ? x : scrubDeep(x)]),
    )
  }
  return v
}

